function parseJSON(text) {
  try {
    return JSON.parse(text);
  } catch (error) {
    console.error("Niepoprawny JSON:", error.message);
    return null;
  }
}

parseJSON('{"imie": "Ala"}'); // { imie: "Ala" }
parseJSON('to nie jest json');  // null (blad zlapany, program dziala dalej)

