function bezpiecznyDzielnik(a, b) {
  try {
    if (b === 0) throw new Error("Dzielenie przez zero");
    return a / b;
  } catch (error) {
    console.log(error.message);
    return null;
  }
}

bezpiecznyDzielnik(10, 2); // 5
bezpiecznyDzielnik(10, 0); // wypisuje "Dzielenie przez zero", zwraca null

