function parsujJSON(tekst) {
  try {
    return JSON.parse(tekst);
  } catch (error) {
    return null;
  } finally {
    console.log("Proba parsowania zakonczona");
  }
}

class BladWalidacji extends Error {
  constructor(message) {
    super(message);
    this.name = "BladWalidacji";
  }
}

const blad = new BladWalidacji("Nieprawidlowe dane");
console.log(blad.name); // "BladWalidacji"
console.log(blad.message); // "Nieprawidlowe dane"
console.log(blad instanceof Error); // true

class BladNieZnaleziono extends Error {
  constructor(message) {
    super(message);
    this.name = "BladNieZnaleziono";
  }
}

function znajdzProdukt(id, produkty) {
  if (!id) throw new BladWalidacji("ID jest wymagane");
  const produkt = produkty.find((p) => p.id === id);
  if (!produkt) throw new BladNieZnaleziono(`Produkt o id ${id} nie istnieje`);
  return produkt;
}

const produkty = [{ id: 1, nazwa: "Laptop" }];

try {
  znajdzProdukt(999, produkty);
} catch (error) {
  if (error instanceof BladWalidacji) {
    console.log(`Blad danych wejsciowych: ${error.message}`);
  } else if (error instanceof BladNieZnaleziono) {
    console.log(`Nie znaleziono: ${error.message}`);
  } else {
    console.log(`Nieoczekiwany blad: ${error.message}`);
  }
}
// "Nie znaleziono: Produkt o id 999 nie istnieje"

function pobierzElement(tablica, indeks) {
  if (indeks < 0 || indeks >= tablica.length) {
    throw new Error(`Indeks ${indeks} poza zakresem`);
  }
  return tablica[indeks];
}

try {
  console.log(pobierzElement([1, 2, 3], 10));
} catch (error) {
  console.log(error.message); // "Indeks 10 poza zakresem"
}

function przetworzDane(dane) {
  try {
    return dane.toUpperCase();
  } catch (error) {
    return "BLAD";
  } finally {
    console.log("Przetwarzanie zakonczone");
  }
}

przetworzDane("tekst"); // "TEKST", + log finally
przetworzDane(42); // "BLAD", + log finally

function test() {
  try {
    return "wynik";
  } finally {
    console.log("finally wykonane"); // to wypisze sie PRZED zwroceniem "wynik"
  }
}

console.log(test());
// "finally wykonane"
// "wynik"
// finally wykonuje sie ZAWSZE, bo silnik JS gwarantuje jego uruchomienie
// jako ostatni krok przed faktycznym opuszczeniem funkcji - nawet jesli
// return zostalo juz "zaplanowane" w try lub catch.
